SELECT s.*, c.class_name AS className FROM student s LEFT JOIN class_info c ON s.class_id = c.id
AND s.status != 'deleted'
AND s.name LIKE CONCAT('%', #{query.name}, '%')
AND s.class_id = #{query.classId}
AND s.status = #{query.status}
ORDER BY s.id DESC

